"""Shared fixtures for the API tests: a fresh vendor working dir per test."""
import datetime
import json
import os
import shutil
import tempfile

from hbonboard.app import build_app

FIXTURES = os.path.join(os.path.dirname(__file__), "fixtures")
TODAY = datetime.date(2026, 10, 9)


def load_signups(name="signups_2026_10.json"):
    with open(os.path.join(FIXTURES, name), encoding="utf-8") as f:
        return json.load(f)


class VendorHome:
    def __init__(self):
        self.path = tempfile.mkdtemp(prefix="idchk-")

    def cleanup(self):
        shutil.rmtree(self.path, ignore_errors=True)


def app_with_members(home, signups):
    app = build_app(today=TODAY, idchk_home=home.path)
    ids = []
    for payload in signups:
        resp = app.post("/members", payload)
        assert resp.status == 201, resp.body
        ids.append(resp.body["id"])
    return app, ids
"""Vendor verdict codes -> member status."""
from hbonboard.models import ACTIVE, KYC_DONE, REJECTED, REVIEW

# 1 = identity matched, 2 = identity did not match; anything else goes to a person
VERDICT_STATUS = {1: ACTIVE, 2: REJECTED}


def status_for(code):
    return VERDICT_STATUS.get(code, REVIEW)


def apply_verdict(member, code):
    member.verdict = code
    member.status = status_for(code)
    member.kyc_state = KYC_DONE
    member.history.append(member.status)
    return member
"""Name helpers shared by the sign-up form and the vendor bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize_name(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) in ("Cc", "Cf"):
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def mask_name(name):
    """홍길동 -> 홍*동, 이도 -> 이*, Kim Minseo -> K********o."""
    if len(name) <= 1:
        return name
    if len(name) == 2:
        return name[0] + "*"
    return name[0] + "*" * (len(name) - 2) + name[-1]


def vendor_name(name):
    """The vendor matches on the registered name without spaces."""
    return name.replace(" ", "")

